"""Day-ahead basis (notes 21.59): the worst fall nights again, with scheduled generation and the day-ahead net position in place of realised output.
Scheduled dispatchable = scheduled total generation - day-ahead wind and solar forecast. Its shock = that minus what the model's curves give at the price."""
import numpy as np, pandas as pd, glob, warnings; warnings.filterwarnings("ignore")
SP = "/tmp/claude-0/-home-user-EpexPredictor/d6125cc0-c431-5b93-a06f-0110cd871ab6/scratchpad"
def rd(nm): d = pd.concat([pd.read_parquet(f) for f in sorted(glob.glob(f"{SP}/entsoe/da/{nm}_*.parquet"))]).sort_index(); d = d[~d.index.duplicated()]; d.index = d.index.tz_convert("UTC"); return d
R = pd.read_parquet(f"{SP}/out/market1n_rows.parquet"); R.index = R.index.tz_convert("UTC"); R["g"] = rd("gen").iloc[:, 0].resample("1h").mean() / 1000; R["w"] = rd("ws").sum(axis=1).resample("1h").mean() / 1000; R["np"] = rd("netpos").iloc[:, 0].resample("1h").mean() / 1000
R["disp_real"] = R.lig + R.coal + R.gasg + R.other + R.psgen; R["disp_da"] = R.g - R.w; R["sh_real"] = R.d_l + R.d_c + R.d_g + R.eS; R["sh_da"] = R.sh_real + R.disp_da - R.disp_real; R["eX_da"] = R.eX + (-R["np"] - R.X); R["adj"] = R.disp_real - R.disp_da; R["gap"] = R.rlreal - R.rl; R.to_parquet(f"{SP}/out/da_rows.parquet")
ok = R.dropna(subset=["adj", "gap"]); print("post-auction adjustment of dispatchable output (realised - scheduled) on the gap realised - published residual load: slope", round(np.polyfit(ok.gap, ok.adj, 1)[0], 2), "corr", round(ok.gap.corr(ok.adj), 2), "| sd of adjustment", round(ok.adj.std(), 2), "GW | sd of shock: realised basis", round(ok.sh_real.std(), 2), "day-ahead basis", round(ok.sh_da.std(), 2), "| import shock sd: realised", round(ok.eX.std(), 2), "day-ahead", round(ok.eX_da.std(), 2))
D = pd.read_csv(f"{SP}/out/miss_look.csv"); D["dfc"] = D.act + D.err - D.prev
def nm(date, col, shift=0):
    t0 = (pd.Timestamp(date, tz="Europe/Berlin") - pd.Timedelta(days=shift)).tz_convert("UTC"); return float(R[col].reindex(pd.date_range(t0, periods=6, freq="1h")).mean())
for c in ("sh_real", "sh_da", "eX", "eX_da", "adj", "gap", "disp_da", "disp_real", "np"): D["c_" + c] = [nm(d, c) - nm(d, c, 1) for d in D.date]; D["l_" + c] = [nm(d, c) for d in D.date]
D.to_csv(f"{SP}/out/miss_look_da.csv", index=False); fall = D[D.dfc <= -2]; hit = fall[fall.err > 1]; okk = fall[fall.err <= 1]; se = lambda x: x.std() / np.sqrt(x.notna().sum())
print(f"forecast falls: {len(hit)} too high, {len(okk)} others (nights with schedule data: {int(hit.c_sh_da.notna().sum())}, {int(okk.c_sh_da.notna().sum())})")
for c, lab in (("sh_real", "dispatchable vs curves, REALISED"), ("sh_da", "dispatchable vs curves, SCHEDULED day-ahead"), ("eX", "net imports vs curve, REALISED"), ("eX_da", "net imports vs curve, DAY-AHEAD position"), ("adj", "post-auction adjustment (realised - scheduled)"), ("gap", "realised - published residual load"), ("disp_da", "scheduled dispatchable, GW"), ("np", "day-ahead net export position")):
    print(f"  change from the night before, {lab:48s} too high {hit['c_' + c].mean():+.2f} +- {se(hit['c_' + c]):.2f} | others {okk['c_' + c].mean():+.2f} +- {se(okk['c_' + c]):.2f}   || level on the night: {hit['l_' + c].mean():+.2f} | {okk['l_' + c].mean():+.2f}")
A = D.dropna(subset=["c_sh_da", "c_eX_da"]); print("all nights: corr of the shift surprise (forecast - true) with the change of the scheduled-dispatchable shock", round(A.du.corr(A.c_sh_da), 2), "realised", round(A.du.corr(A.c_sh_real), 2), "| day-ahead import shock", round(A.du.corr(A.c_eX_da), 2), "realised", round(A.du.corr(A.c_eX), 2))
X = np.column_stack([A.c_sh_da, A.c_eX_da, np.ones(len(A))]); b = np.linalg.lstsq(X, A.u_prev_change.values, rcond=None)[0]; print("true night-to-night change of the shift on the two day-ahead shock changes: coefficients", np.round(b[:2], 2), "R2", round(1 - np.var(A.u_prev_change.values - X @ b) / np.var(A.u_prev_change.values), 2))
